export const homeworkByLesson: Record<number, string> = {
  "1": "## Домашнее задание к занятию 1\n\n1. Выучите буквенно-цифровой код. Напишите напротив чисел соответствующий им буквенный код. Например: 13 ГЖ КХ; 56 ПБ ШЛ; 78 СЗ ВФ; 01 ГЖ: 10 ГЖ НМ.\n\n23- 56- 67- 01- 78- 59- 43- 12- 35- 88- 09- 56- 76- 98- 43- 51- 00- 82- 69- 21- 87- 75- 05- 69- 31- 84- 78- 08- 40- 27- 85- 42- 35- 97- 13- 07- 42- 77- 29- 05- 43- 92- 73- 86- 52- 79- 48- 28- 31- 53- 76- 74- 97- 50- 86- 25- 56- 67- 32- 86- 54- 41- 05- 69- 78- 32- 55- 86- 71- 94- 63- 02- 00- 38- 11- 26- 99- 67- 23- 87- 99- 08- 24- 67- 89- 37- 84- 26- 74-- 96- 68- 94- 25- 36- 86- 86- 85- 37- 63- 64-\n\n2. Напишите напротив букв соответствующие им числа. Например: РЦШЛ 96, ГЖРЦ 19, ДТПБ 25 и т.д.\n\nГЖРЦ- ДТКХ- ПБСЗ- КХВФ- РЦРЦ- ПБЧЩ- ДТГЖ- ШЛСЗ- РЦГЖ- ДТВФ- ГЖНМ- ЧЩРЦ- ПБКХ- ЧЩГЖ- ПБНМ- ВФКХ- СЗГЖ- ДТЧЩ- РЦШЛ- ЧЩНМ- ДТДТ- ПБРЦ - ШЛНМ- СЗГЖ- ГЖРЦ- СЗГЖ- ВФДТ- РЦКХ- ГЖЧЩ- ПБДТ- ШЛВФ- ГЖСЗ- КХПБ- СЗНМ- ВФГЖ- ЧЩШЛ- ДТКХ- ЧЩВФ- КХСЗ- ГЖВФ- ПБНМ- ШЛГЖ- КХЧЩ- ЧЩНМ- ПБРЦ- ГЖГЖ- ДТНМ- ВФГЖ- РЦКХ- ВФНМ- ШЛКХ- НМШЛ- РЦВФ- ГЖКХ- ЧЩПБ- ДТЧЩ- ШЛВФ- ГЖДТ- СЗШЛ- ВФДТ-\n\n3. Запомните слова приемом «Цепочка».\n\nФЛОМАСТЕР ОБЕЗЬЯНА КРУГ МАТЕРИАЛ ФЛАГ ИНДЕЕЦ КОЛЮЧКА МЕТРОНОМ РАСПИСАНИЕ НОЖНИЦЫ ЧАШКА СИГАРЕТЫ НАУШНИКИ КАРТЫ ЗНАМЯ ЧЕРНИЛА ГВОЗДИК ИГОЛКА ЛЕСКА УТКА КИТ СТАКАН МИШЕНЬ РЕМЕНЬ ТЕЛЕФОН\n\n4. Запомните слова приемом «Матрешка».\n\nКОРЫТО КОПЕЙКА ТРАВА ОБЛАКО РАК СПИЧКИ КОВЕР КНОПКА КУБИК ВОЙЛОК ТРУБА ПЕРО НОТЫ ЗНАЧОК СИГАРЕТА ЖУРНАЛ СТЕКЛО КОФЕ ОБУВЬ РОТ ЦЕРКОВЬ МИКРОСКОП КАМЕРА СВЕЧА ДОЛЛАР\n\n5. Подготовьте 10 опорных образов методом Цицерона. Запомните с их помощью следующие слова.\n\nКОМПЬЮТЕР БУМАЖКА ПРУЖИНКА ГЛАЗ ПЕНЬ ФОТОПЛЕНКА ДЕЛЬФИН ПАМЯТНИК ПЛАНЕТА ДЫРКА\n\n6. Подготовьте 10 опорных образов методом свободных ассоциаций. Запомните с их помощью следующие слова.\n\nПРОВОД ПЕЧАТЬ ВАЗА ИГРУШКА ФОТОГРАФИЯ -УДЛИНИТЕЛЬ ЩЕНОК ОДЕКОЛОН ГИПС ЗАНАВЕСКА\n\n7. Подготовьте 4 опорных образа методом Цицерона. К каждому выделенному образу привяжите ассоциацией первые слова запомненных вами цепочек. Мысленно, вслух или письменно вспомните сразу все 70 слов домашнего задания.",
  "2": "## Домашнее задание к занятию 2\n\n1. Выучите наизусть образные коды чисел от 00 до 20. Читайте числовую таблицу, называя вслух соответствующие числам образы. Перекодировку чисел в слова доведите до автоматического уровня. При этом числа таблицы должны перекодироваться вами в слова со скоростью не более 1 секунды на число и без задержек. Если какое-либо число перекодируется в образ с задержкой, заучите его отдельно.\n\n20 04 09 01 19 06 15 12 18 10\n\n02 09 01 12 17 05 07 11 18 04\n\n09 13 20 00 17 07 15 19 05 08\n\n13 01 19 10 06 20 08 15 09 02\n\n11 19 13 00 13 07 09 00 20 16\n\n11 17 19 13 15 05 17 04 01 09\n\n00 13 01 08 06 16 18 07 02 18\n\n09 03 20 19 16 03 18 14 09 12\n\n2. Запомните слова приемом «Цепочка». При припоминании перекодируйте слова в цифры в соответствии с буквенно-цифровым кодом (столетник -726…)\n\nГИТАРА КОРОБКА МОТОЦИКЛ КРЕМ КАССЕТА ГОРЕЛКА ТОРШЕР ВИНТ ПАПКА СТЕКЛО КАТУШКА ПЫЛЕСОС ТЮЛЬПАН ГВОЗДЬ ОБМОТКА КРЕСЛО КАРТИНА АЛЬБОМ НАУШНИКИ ПЛАНЕТА ДОМИК ОБЛАКА ТРАВА ВЫКЛЮЧАТЕЛЬ ДВИГАТЕЛЬ ЗАМАЗКА ВЕНТИЛЯТОР ЛЕПЕСТОК ВОЛОСЫ ОКРУЖНОСТЬ\n\n3. Преобразуйте слова в образы приемом символизации. Запомните последовательность приемом «Матрешка».\n\nАККУРАТНОСТЬ ГЛУПОСТЬ ЗЛОСТЬ УСИДЧИВОСТЬ ГОРДОСТЬ СКОРОСТЬ НЕЖНОСТЬ ВЕЖЛИВОСТЬ ЖАРА ВЛАЖНОСТЬ БЕГАТЬ СМОТРЕТЬ ЛЮБОВАТЬСЯ НАСЛАЖДАТЬСЯ ВЕРИТЬ РАЗМЫШЛЕНИЕ НЕНАВИСТЬ ТРУДОЛЮБИЕ БЕСПЕЧНОСТЬ\n\nПолучившиеся в результате кодирования символы запишите в тетрадь для анализа на занятиях. Умение быстро подбирать образы для такого рода слов пригодится вам в дальнейшем при запоминании иностранных слов.\n\n4. Преобразуйте информацию в образы приемом привязки к хорошо знакомой информации. Запомните последовательность образов приемом «Цепочка».\n\nпланета ЮПИТЕР штат МЭН штат ДЖОРДЖИЯ гор. ТУЛА село ПУШКИНО МЛЕЧНЫЙ ПУТЬ гор. КЛИН аэропорт БЫКОВО гор. СЕРПУХОВ гор. ГЖЕЛЬ 1851 год гор. ПРОТВИНО\n\nПолучившиеся при перекодировании образы запишите в тетрадь для анализа на занятиях.\n\n5. Преобразуйте информацию в образы приемом перекодирования по созвучию. Запомните последовательность образов приемом «Матрешка».\n\nДАКОТА ТЕННЕССИ АЛЯСКА АЙОВА ЖЕРАР КАССЕЛЬ КЕМАЛЬ КЕПС КЛАССОН ПИФОН СМУШКА ФУЛЯР ФУКУС ГИББС ЗОЛИ ИНТРАДА КАСАИ ЛЕСКО ЛИОН\n\n6. Запомните бессмысленные буквосочетания приемом образования слова по слогам и приемом образования ассоциативной связи. В ассоциации выделите основу. Запомните последовательность методом Цицерона (по основам).\n\nПример. МОНВИЛТРО ассоциация «монитор вилка трон». -Образ «монитор» основа ассоциации- - используется для запоминания последовательности, и к нему привязываются другие образы.\n\nКЛАСТРОБЛ КНУРУБГАЙ ФИЛРКЖСУМ РУЧАЛЬПРИ ФОТКНИМАГ ТОРМОРФИЛ КИНТЕЛМОН ВИНГРОМИШ МАСОКУЛИН СТЕОБОГЛА ШЕРОБЛКУР УТКОГУЛЕК",
  "3": "## Домашнее задание к занятию 3\n\n1. Выучите фиксированные коды на числа от 21 до 40. Повторяйте числа от 00 до 20. После заучивания образных кодов тренируйтесь в перекодировании чисел в образы по таблице случайных чисел. Скорость перекодирования должна быть не более одной секунды на число, без задержек. Если число перекодируется с задержкой, заучите его дополнительно, представляя мысленно образ самого числа на фоне его образного кода (см. мыслительная операция «Наложение образов»).\n\n10 17 01 37 18 25 34 30 05 28\n\n33 40 00 03 26 38 20 06 13 04\n\n12 21 16 22 35 29 15 24 19 07\n\n09 14 23 31 39 02 08 11 27 32\n\n01 26 33 29 40 17 09 37 14 04\n\n38 05 22 16 28 34 36 06 12 18\n\n10 02 11 15 30 24 08 27 21 13\n\n03 07 19 25 39 20 23 31 35 32\n\n10 05 26 30 29 07 01 33 14 23\n\n03 06 15 09 37 13 16 20 17 04\n\n22 27 31 40 00 34 21 08 12 24\n\n18 02 19 28 36 38 32 38 23 11\n\n08 30 37 28 17 10 29 40 01 25\n\n04 26 33 05 21 16 09 18 06 13\n\n23 11 14 07 19 22 38 02 31 32\n\n27 32 12 07 21 09 27 18 04 39\n\nЕсли у вас дома есть метроном, включите его и перекодируйте таблицу под метроном, постепенно увеличивая скорость перекодирования. Скорость увеличивайте только в том случае, если числа перекодируются вами без задержек.\n\n2. В течение дня мысленно повторяйте запомнившиеся исторические даты, последовательно выводя их из памяти. Не прерывайте процесс припоминания, пока не вспомните все даты. Очень важно не то, что вы можете воспроизвести информацию без ошибок, а то, чтобы вы это делали как можно чаще. Навык запоминания формируется в процессе запоминания и припоминания.\n\n3. Запомните все штаты США. Закрепите их в памяти методом активного повторения. Информация должна воспроизводиться без задержек и легко. Очень важно тренироваться вспоминать сведения. Как показывает практика, процесс припоминания иногда протекает сложнее, чем процесс запоминания.",
  "4": "## Домашнее задание к занятию 4\n\n1. Выучите образные коды двузначных чисел до 60. Тренируйтесь в перекодировании по таблице случайных чисел.\n\n20 12 15 52 32 11 01 07 45 25\n\n04 24 46 26 25 39 53 08 36 55\n\n04 56 38 03 37 02 19 60 07 09\n\n34 13 27 12 33 37 44 30 18 18\n\n40 15 06 13 22 38 51 54 60 41\n\n02 49 17 47 29 05 28 43 23 27\n\n16 40 14 30 53 16 06 55 39 46\n\n36 04 27 48 41 35 13 10 58 03\n\n31 10 31 09 01 08 47 07 29 12\n\n25 09 18 14 20 12 21 57 23 34\n\n59 11 44 20 22 08 59 42 29 22\n\n41 51 32 57 45 56 35 14 01 16\n\n02 17 19 50 28 26 31 25 50 24\n\n03 24 23 05 06 42 21 53 11 54\n\n19 33 05 48 58 17 30 49 27 10\n\n21 07 24 51 12 53 49 34 52 18\n\n2. Запомните даты, связанные с историей фотографии.\n\n1694 Гомберг открыл светочувствительность азотнокислого серебра\n\n1801 Юнг предложил теорию трехкомпонентного цветного зрения\n\n1837 Дагер изобрел первый фотографический метод получения качественного изображения на солях серебра\n\n1839 (7. 01) Араго доложил на заседании Французской академии наук об изобретении Дагера - день рождения фотографии\n\n3. Запомните последовательность аминокислот.\n\nАЛАНИИ ВАЛИН ЛЕЙЦИН ИЗОЛЕЙЦИН ПРОЛИН ФЕНИЛАЛАНИН ТРИПТОФАН МЕТИОНИН ГЛИЦИН СЕРИИ ТРЕОНИН ЦИСТЕИН ТИРОЗИН АСПАРАГИН ГЛУТАМИН АСПАРАГИНОВАЯ КИСЛОТА ГЛУТАМИНОВАЯ КИСЛОТА ГИСТИДИН ЛИЗИН АРГИНИН\n\n4. Запомните последовательность точных дат.\n\n24 апреля 1350 г. 12 июля 1396 г. 21 мая 1532 г. 08 декабря 1562 г. 21 октября 1932 г. 09 июня 1560 г.\n\n5. Запомните слова под порядковыми номерами.\n\n1. БОГАЧ 11. ГОСПОДИН 21. ПЛЮС\n\n2. ГОД 12. ШОФЕР 22. ИГОЛКА\n\n3. БОМБА 13. БАРИТОН 23. ОБОИ\n\n4. МОЗГ 14. ВНЕШНОСТЬ 24. ЦВЕТОК\n\n5.5ОПЫТ 15. СЛОВО 25. РУБАШКА\n\n6. ЗДАНИЕ 16. АНГЛИЯ 26. СТРУНА\n\n7. ВЕЩЬ 17. ЛАСТИК 27. ШНУР\n\n8. КНИГА 18. КАКТУС 28. ТЕРКА\n\n9. САТАНА 19. ТЕЛЕФОН 29. ХВОСТ\n\n10.ЛЕС 20. СЧЕТЫ 30. ПЛАСТИК",
  "5": "## Домашнее задание к занятию 5\n\n1Выучите наизусть фиксированные коды двузначных чисел (от 61 до 80). Повторяйте и закрепляйте в памяти предыдущие числа.\n\n2. Переводите числа в образные коды. Добивайтесь, чтобы перекодирование осуществлялось без задержек.\n\n13 56 68 33 02 42 09 29 11 57\n\n19 41 26 58 77 18 44 48 36 72\n\n61 05 75 32 12 37 04 51 76 35\n\n20 55 01 38 67 10 31 17 22 50\n\n06 14 59 78 03 43 08 45 28 64\n\n27 39 69 25 53 23 16 71 66 73\n\n62 60 80 74 79 46 65 30 49 52\n\n40 07 54 15 47 24 21 34 70 63\n\n3. Запомните слова строго под их порядковыми номерами.\n\n1. НОМЕР 2. ЭКРАН 3. ВСТРЕЧА 4. ВЫХОД\n\n5. ГАРАНТИЯ 6. КЛАВИАТУРА 7. ЭЛЕКТРОН 8. ВСЕЛЕННАЯ\n\n9. ПУТЬ 10. ДОБРО 11. СЛУЖБА 12. МИР\n\n13. РАЗГРУЗКА 14. ЭВМ 15. ФУНДАМЕНТ 16. ПРИНЦИП\n\n17. ЗВУК 18. ПРОБЛЕМА 19. УДАР 20. СЧЕТ\n\n21. АМЕРИКА 22. ЭФФЕКТ 23. БОЛТ 24. МЕДЬ\n\n25. ПОЧТА 26. БИБЛИЯ 27. БАЗА 28. РЕФЕРАТ\n\n29. МОРКОВКА 30. СОЮЗ 31. ИНТЕРЕС 32. АВТОР\n\n33. ТЕЛЕВИДЕНИЕ 34. УДОЧКА 35. ЛАБОРАНТ 36. ОСНОВАНИЕ\n\n37. ПРОЦЕНТ 38. КРИТИКА 39. ГРАФИКА 40. НОВОСТИ\n\n41. МЕСТНОСТЬ 42. КОМИССИЯ 43. УГОЛОК 44. ГАЗЕТА\n\n45. СПОРТ\n\n4. Запомните последовательность анекдотов.\n\nЧеловек читает в газете, что в Лос-Анджелесе каждый час под машину попадает один человек.\n\n- Боже, вздыхает он, вот не везет бедняге.\n\nКогда Марк Твен получил приглашение на похороны одного сенатора, он сказал:\n\n- Я отказался присутствовать на похоронах этого человека, но послал вежливое письмо, в котором написал, что от души приветствую это мероприятие.\n\n- Извините, но мне кажется, что я видел ваше лицо где-то в другом месте.\n\n- Этого не может быть. Свое лицо я постоянно ношу на одном и том же месте.\n\nМолодой человек приходит к богатому промышленнику, на дочери которого он хочет жениться. Промышленник говорит:\n\n- Молодой человек, я навел справки о вашем прошлом и должен сказать…\n\nМолодой человек прерывает его:\n\n- Я тоже навел справки о вашем прошлом и должен вам сказать…\n\n- Ладно, давайте поговорим о чем-нибудь другом.\n\nМама, мышка прыгнула в бидон с молоком!\n\n- Ты вытащила ее?\n\n- Нет, но я бросила туда кота!\n\nСсора в молодой семье.\n\n- Да ты, оказывается, просто эгоист. Моя жена, моя квартира, моя зарплата. Мое, мое… Нет ничего твоего, Есть только наше. Ты запомнил? Кстати, что это ты там ищешь в шкафу?\n\n- Наши брюки, - отвечает муж.\n\nЭкспресс «Южный Тихоокеанский» несся вдоль границ одного из самых крупных в Техасе скотоводческих ранчо. Один из пассажиров пристально всматривается в огромные стада, пасущиеся вдоль дороги. Когда, наконец, поезд миновал территорию ранчо, он повернулся к соседу и заметил:\n\n- Порядочное стадо на этом ранчо. Я насчитал 11 420 голов. Сосед изумленно уставился на него.\n\nПросто непостижимо! - объявил он. Между прочим, я владелец этого ранчо и точно знаю, что у меня именно 11 420 голов скота. Бога ради, каким образом вы ухитрились сосчитать их, когда наш поезд делает 60 миль в час?\n\n- О, это довольно просто, если знать систему, - отвечал математик. Требуется лишь посчитать ноги и разделить на четыре.\n\n- Тетя Власта, ты что, сама есть не умеешь?\n\n- С чего ты это взял, Пепичек?\n\n- Когда ты сообщила о своем приезде, папа сказал маме: «Снова целую неделю нам придется кормить твою тетку!»\n\n- Добрый вечер! Я хочу сказать, что ваша дочь согласна быть моей супругой!\n\n- Сами виноваты! Зачем надо было каждый вечер приходить к нам в гости?\n\n5. Запомните формулы техникой запоминания формул.\n\nСКОРОСТЬ УПОРЯДОЧЕННОГО ДВИЖЕНИЯ ЭЛЕКТРОНОВ В ПРОВОДНИКЕ\n\nu = I: (enS)\n\nu - скорость упорядоченного движения электронов в проводнике\n\nI - сила тока\n\nе - модуль заряда электрона\n\nn - число электронов\n\nS - площадь поперечного сечения проводника\n\nРАВНОМЕРНОЕ ДВИЖЕНИЕ ПО ОКРУЖНОСТИ\n\nv = 2nR\n\nv - модуль скорости\n\nт - частота обращения\n\nR - радиус",
  "6": "## Домашнее задание к занятию 6\n\n1. Выучите оставшиеся 20 чисел фиксированных образных кодов. Тренируйтесь в их перекодировании по таблице случайных чисел. Очень важно уметь быстро переводить числа в образы для быстрого запоминания числовой информации (телефоны, адреса и т.п.).\n\n21 33 65 14 48 16 79 03 42 88\n\n46 81 05 34 78 43 56 24 59 10\n\n64 99 20 55 01 15 36 41 87 50\n\n98 32 84 06 35 47 02 58 09 97\n\n04 45 54 13 31 23 57 19 76 74\n\n61 22 96 67 49 86 08 37 40 85\n\n70 72 17 53 30 18 69 25 28 60\n\n75 80 68 07 44 95 11 63 82 94\n\n66 93 27 73 52 26 91 38 51 89\n\n71 83 77 12 92 39 62 29 90 00\n\n2. Запомните слова под порядковыми номерами. Время запоминания одного слова - примерно 6-8 секунд.\n\n1. АРМЕНИЯ 2. МИНУТА 3. ЗАКОН 4. ПРОЦЕСС\n\n5. ГОРОХ 6. ПОЛИТИКА 7. СТАТЬЯ 8. УГОЛ\n\n9. КРЫША 10. КОМЕДИЯ 11. АДВОКАТ 12. ЗЯТЬ\n\n13. ПОГРОМ 14. АЛКОГОЛЬ 15. ДОЛГ 16. ДИСПАНСЕР\n\n17. ФОРМА 18. МАРСИАНЕ 19. ИЮНЬ 20. УКАЗАНИЕ\n\n21. ВОЙНА 22. АТМОСФЕРА 23. ПРАКТИКА 24. КОМИССАР\n\n25. ШПИОН 26. ТАЛАНТ 27. ПИСЬМО 28. ПОРТРЕТ\n\n29. ВОЗРАСТ 30. ДЕРЗОСТЬ 31. ВЕРА 32. МОРЕ\n\n33. ФОТО 34. РЕДАКТОР 35. ВЫСОТА 36. КОНЬКИ\n\n37. БОРОДА 38. ПОРТРЕТ 39. СКАНДАЛ 40. ВЫСТАВКА\n\n41. БЕГ 42. ЧЕРДАК 43. АТМОСФЕРА 44. СПРАВКА\n\n45. ГОРОД 46. ПЕДАГОГ 47. РАЗРУХА 48. ШТАНГА\n\n49. РЕАЛЬНОСТЬ 50. ТРУД 51. ФИЛИН 52. ОТЛИЧНИК\n\n53. ИЗДЕЛИЕ 54. СПИСОК 55. ВРАГ 56. МАГАЗИН\n\n57. ДЕФИЦИТ 58. БУМАГА 59. ЛОГИКА 60. РАЙОН\n\n61. ОРГАН 62. ЕВРОПА 63. ЛИДЕР 64. ЦЕНТР 65. ФОНД 66. КРОХА 67. НУЖДА 68. СЧАСТЬЕ 69. ВРЕМЯ 70. ЦЕХ 71. ПАР 72. КУРСК\n\n73. ТЕХНИКА 74. СПОСОБ 75. ДЕТИ 76. БЛОКНОТ\n\n77. ЖЕНЩИНА 78. ТОВАР 79. ТЕТРАДЬ 80. ПРИБЫЛЬ\n\n81. КАМЕНЬ 82. АПТЕКА 83. НОС 84. ТОРМОЗ 85. РЫНОК 86. САША 87. ОЧКИ 88. МОЛОДЕЖЬ\n\n89. АРМИЯ 90. МОНЕТА 91. ОБОРОНА 92. КУЛЬТУРА\n\n93. СМОЛА 94. СТАРИК 95. БЕСЕДКА 96. КАРУСЕЛЬ\n\n97. МЕТРОНОМ 98. МЫЛО 99. ПАПКА\n\n2. Вспомните хронологическую таблицу (занятие 6) последовательно с начала до конца, без перерыва. Запишите на бумаге, проверьте. Потерянную из памяти информацию запомните вновь. Припоминайте хронологическую таблицу в течение дня (в автобусе, метро, электричке). Потренируйтесь повторять разными способами: только цепочками опорных образов, с полной расшифровкой, с прорисовкой чисел.\n\n3. На фотографиях выделите отличительные признаки. Запомните отличительные признаки приемом «Матрешка». Вспомните последовательно отличительные признаки, стараясь мысленно представить обобщенный образ лица. Закодируйте в образы фамилии, имена и отчества. Фамилии привяжите к отличительным признакам. Имя и отчество запомните на разные подобразы образа, обозначающего фамилию. Вспомните упражнение (без книги): отличительный признак, образ лица, фамилию, имя и отчесство.\n\nОтличительный признак\n\n«Скулы»\n\nКрюкова\n\nТатьяна\n\nМихайловна\n\nОтличительный признак\n\n«Шляпа»\n\nСивоглазов\n\nАндрей\n\nВикторович\n\nОтличительный признак\n\n«Висок»\n\nПетровская\n\nГалина Евгеньевна\n\nОтличительный признак\n\n«Писатель»\n\nЖиличкина\n\nАнастасия Аркадьевна\n\nОтличительный признак\n\n«Бусы»\n\nЧамаева\n\nЕлена Викторовна\n\nОтличительный признак\n\n«Большие очки»\n\nЕжков\n\nВалентин Егорьевич\n\nОтличительный признак\n\n«Седая борода»\n\nГерчук\n\nЮрий Александрович\n\n---\n\n## Домашнее задание к занятию 7\n\n42. Обобщение пройденного материала\n\nПовторите приемы запоминания последовательности образов.\n\n1. Прием «Цепочка». Этим приемом запоминаются горизонтальные взаимосвязи, например, последовательность точных сведений в отрывке текста.\n\n2. Прием «Матрешка». Этим приемом запоминаются вертикальные взаимосвязи. Например: последовательность абзацев, последовательность дат хронологической таблицы, последовательность названий при запоминании телефонных номеров и смешанных таблиц. Прием «Матрешка» позволяет экономить опорные образы. С помощью этого приема запоминаемые сведения связываются в блок. Разные блоки информации дополнительно фиксируются на хорошо закрепленную в памяти последовательность опорных образов (например, методом Цицерона).\n\n3. Метод Цицерона. Применяется преимущественно для запоминания последовательности первых образов разных ассоциативных цепочек и блоков информации. Рекомендуем закреплять в памяти опорные образы, многократно запоминая на них случайные числа (на программе «Мастер запоминания»). Закрепленную систему опорных образов можно в дальнейшем использовать для долговременного запоминания блоков информации.\n\n4. Прием свободных ассоциаций. Применяется для расширения других методов. Например, для образования дополнительных образов к отличительному признаку при запоминании информации о человеке, формул и постоянных величин. Этим же приемом можно получить дополнительные образы для образных кодов чисел и букв алфавита.\n\n5. Прием запоминания на разные части одного образа. Применяется для запоминания образных кодов. Любые образные коды должны запоминаться только изолированно друг от друга, через другой образ. (Запоминание имени и отчества на образе фамилии, запоминание чисел телефона на образе «хозяина» телефонного номера.)\n\n6. Прием выделения невидимых частей образа. Используется для создания надежной системы опорных образов и для «сборки» блока информации на одном образе (запоминание телефонных номеров в алфавитном порядке, сбор нескольких цепочек на одном образе прием «фокусировки» информации).\n\n7. Прием возврата. При запоминании этим приемом в качестве опорных образов используются разные части предыдущего образа запоминаемой последовательности. Этот прием объединяет в себе прием «Цепочка» и «Прием запоминания на разные части образа». Применяется для изоляции образных кодов при запоминании точных сведений в отрывке текста.\n\n8. Запоминание под порядковыми номерами (на основе фиксированных образных кодов чисел). Применяется для оперативного запоминания информации с последующей перезаписью ее другими методами. Вы можете в течение дня записывать точные сведения в свою память под порядковыми номерами; затем не спеша систематизировать эту информацию, собрав ее в блоки или тематические последовательности.\n\n9. Запоминание в алфавитной последовательности. Применяется для запоминания сведений в алфавитном порядке. Вы можете запоминать адреса, телефоны, фамилии и другую информацию в порядке следования букв в алфавите без предварительной систематизации.\n\n10. Запоминание на хорошо закрепленную в памяти последовательность образов. Последовательности слов, которые вы запоминаете в упражнениях, можно применять для формирования системы опорных образов. Привязав к десяти опорным образам (метод Цицерона) короткие цепочки по 10-20 образов, вы получите 100-200 «Ячеек» для долговременного запоминания соответствующего количества блоков информации.\n\nВсе эти приемы запоминания последовательностей образов применяются как отдельно, так и в различных комбинациях. Составление комбинаций - импровизационное и зависит от целей запоминания и от вида запоминаемых сведений.\n\nДля чего запоминать последовательность информации\n\n1. Для того, чтобы воспроизвести всю информацию целиком, без подсказок и наводящих вопросов (активное припоминание).\n\n2. Для того, чтобы обеспечить себе возможность в течение нескольких дней равномерно и без пропусков повторять и закреплять новые сведения, извлекая их из своей памяти (метод активного повторения).\n\nВсегда при запоминании учитывайте мнемотехнические эффекты\n\n1. Любые образные коды нельзя связывать между собой в ассоциации (образные коды двузначных чисел, дней недели, названий месяцев, имен и отчеств, математических знаков и элементов формул, учебных дисциплин при запоминании расписаний и пр.)\n\n2. Формирование у вас рефлекторной связи тестируется по образным кодам, следующим в случайном порядке. Кодировку элементов информации в образные коды необходимо проводить очень быстро (0,5-1 секунда на образ). Для тренировки и тестирования очень удобны карточки. С их помощью быстро получаются случайные комбинации (путем простого перемешивания).\n\n3. Для нейтрализации «Эффекта сворачивания ассоциативных цепочек» информацию большого объема разбивайте на несколько коротких последовательностей (не более 10 образов в каждой). Они собираются вместе методом Цицерона или приемом фокусировки на одном образе.\n\n4. Для нейтрализации «Эффекта стирания ассоциаций» помните, что вновь образованные взаимосвязи самопроизвольно разрушаются через короткий промежуток времени (примерно через 40 минут). Для сохранения ассоциаций требуется их мысленное повторение (активизация).\n\n5. Применяя мнемотехнику, вы всегда сможете определить, какой образ у вас уже занят. При долговременном запоминании не используйте повторно занятые образы. Это приведет к стиранию предыдущей информации. Образы легко видоизменяются. Поэтому при необходимости использовать уже занятые образы, применяйте мыслительные операции «Видоизменение» и «Трансформация».\n\n6. Для быстрого получения «Эффекта непосредственного припоминания» (формирование рефлекторной связи) запомнившиеся в зрительных образах сведения необходимо мысленно повторять с применением операции «Наложение образов», мысленной прорисовки и проговаривания на фоне опорного образа. При этом происходит образование ассоциативных связей между разными анализаторными системами, что равносильно долговременному (пожизненному) запоминанию.\n\n7. Для закрепления сведений в речевом анализаторе (фамилии, названия, термины) используйте большую инертность речевого анализатора (4 секунды). Считанные со зрительных образов слова (5 слов) легко удерживаются в сознании и могут быть повторены вами очень быстро уже без опоры на зрительные образы. При нескольких мысленных повторениях речевая память запоминает сразу связку слов. Любая точная информация, закрепленная таким способом, припоминается так же легко, как стихи.\n\n8. Не забывайте использовать естественные ассоциации (взаимосвязи, образованные естественным путем при восприятии). Чтобы мозг что-то запомнил (это относится к зрительным образам), достаточно несколько секунд просто смотреть на нужную картинку (повторите метод выделения отличительного признака и технику запоминания фотографий). Аналогичным способом можно зафиксировать в памяти последовательность иллюстраций в учебнике или картины.\n\n9. Изучив какую-либо технику, отрабатывайте ее на нужной вам информации. Любые сведения запоминаются примерно одинаково. Из разных приемов и методов можно как из кирпичиков собирать новые техники запоминания, настраивая мнемотехнику на разные учебные дисциплины.\n\nЗадание\n\nВ свободное время разработайте свою технику запоминания: расписания движения электричек, таблицы Менделеева, экзаменационных билетов по правилам дорожного движения, юбилеев и дней рождений, статей законов. Запоминать эту информацию не нужно. Просто подумайте, как наиболее целесообразно запомнить тот или иной вид информации, применяя комбинацию изучаемых вами приемов и методов запоминания.\n\nУпражнения\n\n1. Преобразуйте буквы алфавита в фиксированные образные коды. Добивайтесь автоматизма кодирования (с минимальным временем).\n\nЛ Й Ч З Л К У Э Е Х\n\nЖ А У Ф И Б П Ф О Я\n\nШ Е М А Ш Н Б А Й О\n\nЦ В Д Х С И Л Д П Ж\n\nТ С М Т Э Щ Ю Н Ю Г\n\nЛ Ч Щ Р Г Я Р В З Ц\n\n2. К каждой букве алфавита привяжите ассоциативной связью по одному образу и мысленно разберите каждый образ на три части. Представляйте каждую часть отдельно.\n\nА АРКА ПАЧКА (выделить три образа)\n\nБ БУР СПИЧКИ (выделить три образа)\n\nВ ВИНТОВКА ЧАСЫ (выделить три образа)\n\nГ ГРАБЛИ МОНИТОР (выделить три образа)\n\nД ДОСКА БОТИНОК (выделить три образа)\n\nЕ ЕДИНИЦА ПИСТОЛЕТ (выделить три образа)\n\nЁ -ЁРШИК ЛАМПОЧКА (выделить три образа)\n\nЖ ЖАРОВНЯ ПЕНАЛ (выделить три образа)\n\n3 ЗЕМЛЯНИКА ЗАЖИГАЛКА (выделить три образа)\n\nИ ИЛЛЮМИНАТОР ПРИЕМНИК (выделить три образа)\n\nЙ ЙОГУРТ КНИГА (выделить три образа)\n\nК КОФЕ КОЛЕСО (выделить три образа)\n\nЛ ЛАПТИ ТЕЛ. ТРУБКА (выделить три образа)\n\nМ МАЙКА ЦВЕТОК (выделить три образа)\n\nН НИТКИ ФОТОАППАРАТ (выделить три образа)\n\nО ОБРУЧ КАЛЬКУЛЯТОР (выделить три образа)\n\nП ПАКЕТ ГИТАРА (выделить три образа)\n\nР РАПИРА ДЖИНСЫ (выделить три образа)\n\nС СУНДУК СТУЛ (выделить три образа)\n\nТ ТАБЛЕТКА СТУПНЯ (выделить три образа)\n\nУ УКРОП ЛИФТ (выделить три образа)\n\nФ ФИШКА МАШИНА (выделить три образа)\n\nX ХАЛАТ ВИОЛА (выделить три образа)\n\nЦ ЦЕПЬ КРОКОДИЛ (выделить три образа)\n\nЧ ЧЕРНИКА УЛИЧНЫЙ ФОНАРЬ (выделить три образа)\n\nШ ШАЙБА ЦЕПОЧКА (выделить три образа)\n\nЩ ЩЕКОЛДА ФУРАЖКА (выделить три образа)\n\nЭ ЭКРАН ПИАНИНО (выделить три образа)\n\nЮ ЮБКА КОМАР (выделить три образа)\n\nЯ ЯНТАРЬ НАУШНИКИ (выделить три образа)\n\nНа восьмом занятии вы будете использовать эту систему опорных образов для запоминания телефонных номеров в алфавитном порядке.\n\n3. Подготовительное упражнение к технике запоминания текстового материала. Возьмите любую газету или журнал. Прочитав один абзац, запишите на бумаге максимально сжато основную мысль прочитанного абзаца. Обозначьте абзац зрительным образом. Проработайте несколько десятков абзацев. Запомните последовательность абзацев по словесным опорам. Перескажите без точной информации.\n\nЧасто при запоминании текстов приходится либо объединять несколько абзацев в один, либо из одного абзаца выделять несколько самостоятельных. Для наведения логического порядка в тексте иногда даже возникает необходимость перестановки абзацев (совмещение разных абзацев, одинаковых по смыслу).\n\n---\n\n## Домашнее задание к занятию 9\n\n1. Запомните энциклопедические сведения.\n\nПо данным польской статистики, за 68 лет жизни средний поляк тратит на бритье 91250 минут, то есть 63,4 дня. Одевание и раздевание занимает 523 дня, а за столом поляк проводит 1046 дней и 16 часов.\n\nСогласно опубликованным в Великобритании официальным данным, общее количество морских и речных судов в Шотландии и в Уэльсе превышает численность населения этих частей страны.\n\nЧтобы точно выяснить, какой ущерб могут нанести крысы, в одном американском универмаге провели оригинальный опыт. Крысам там была предоставлена полная свобода действий. За два месяца такой вольной жизни крысы уничтожили или привели в негодность 1300 мешков соли, 1724 мешка кофе, 14 тонн муки и около 200 тони сахара.\n\nВ польском городе Щецине недавно был организован конкурс на самую длинную и красивую женскую косу. Из 65 претенденток на главный приз жюри выбрало Ванду Маргулу из Старгарда. Длина ее косы - 144 сантиметра. Победительница ухаживала за косой почти двадцать лет.\n\n27 ноября 1978 года 58-летний француз Эммануэль Витриа отметил 10 лет своего второго рождения. 27 ноября 1968 года марсельский хирург Эдмонд Анри пересадил ему сердце двадцатилетнего солдата. Успех пересадки Витриа объясняет своей волей к жизни: «За жизнь нужно цепляться, никогда не думая о прошлом». Главный гость на юбилее не присутствовал: хирург Эдмонд Анри скончался от болезни сердца.\n\nСамая забавная в мире телефонная книга издается на Бермудских островах. Здесь кроме фамилий абонентов указываются их прозвища. Так, среди проживающих на островах Смитов можно найти по книге Смита-Размазню, Длинного Смита и Смита-Счастливчика.\n\nСамый большой водопад Земли находится… под водой. В Бассовом проливе между Австралией и Тасманией на дне имеется скальный уступ, с которого ежесекундно падает на 400 метров около 30 тысяч кубометров воды. Ширина этого каскада - примерно 150 километров. Австралийский океанолог Стюарт Годфри утверждает, что это не только самый большой водопад на нашей планете, но и единственный подводный водопад. Впрочем, рельеф океанского дна изучен еще не полностью.\n\nКак сообщила недавно лондонская газета «Тайме», в индийском штате Мадхья-Прадеш двухлетняя девочка убила кобру. Девочка играла в саду на глазах у родителей, когда из высокой травы ей навстречу поднялась голова змеи. Никто из взрослых не успел сделать ни шагу, а девочка бросилась на кобру и укусила ее. Змея испустила дух. Перепуганные родители доставили дочь в больницу, но врачи, не видя никаких причин держать девочку в больнице, в тот же день отпустили ее домой.\n\nВ Австралии на чемпионате улиток участница состязаний под номером 806 промчалась по тартановой дорожке длиной 182 сантиметра ровно за 19 минут, опередив всех других.\n\nДо сих пор принято было считать, что англичане стоят на первом месте в мире по потреблению чая. Пьют они его действительно много: 1650 чашек на душу населения в год, то есть 4,5 чашки в день. Однако сейчас, как вытекает из опубликованных в Лондоне данных, вперед вышли ирландцы: на каждого жителя Ирландии приходится в год 1724 чашки чая.\n\n2. Запомните таблицу.\n\nКрупнейшие реки мира\n\nНазвание Длина (км)\n\nНил (с Кагерой) 6671\n\nАмазонка (с Мараньоном) 6437\n\nМиссисипи (с Миссури) 6420\n\nЯнцзы 5800\n\nОбь (с Иртышом) 5410\n\nХуанхэ 4845\n\nМеконг 4425\n\nАмур (с Аргунью) 4440\n\nЛена 4400\n\nПарана (с Парагваем) 4380\n\nКонго (с Луалабой) 4320\n\nМакензи 4250\n\nНигер 4160\n\nЕнисей 4102\n\nМуррей (с Дарлингом) 3750\n\nВолга 3530\n\n3. Запомните таблицу.\n\nМеры массы\n\n1 берковец 163,8 кг\n\n1 пуд 16,38 кг\n\n1 фунт 409,5 г\n\n1 лот 12,80 г\n\n1 золотник 4,266 г\n\n1 доля 44,43 мг\n\n---\n\n## Домашнее задание к занятию 10\n\n1. Запомните энциклопедические сведения с сохранением их последовательности и всей точной информации.\n\nТопаз весом в 117 килограммов найден в Бразилии и выставлен в настоящее время в Венском музее естественной истории. Но это не самый большой топаз в мире. В Нью-Йоркском музее естественной истории есть, например, топаз, весящий 270,3 килограмма, тоже найденный в Бразилии.\n\nАвтомобиль-вертолет - одна из моделей, которые вызвали наибольший интерес на соревновании молодых моделистов в ФРГ. Модель выполнена из дерева, вес ее - 18 килограммов, диаметр ротора - 160 сантиметров. На земле ее скорость - 10- 12 километров в час, а в воздухе - до 60.\n\nЭйфелева башня недавно ремонтировалась. Леса были сооружены на высоте 200 метров между вторым и третьим ярусами башни. Для монтажа лесов пришлось поднять наверх 40 тонн железа (каркас лесов), 70 тонн элементов подмостков и сто кубометров досок.\n\nЯпонский астроном Х.Мори открыл ночью 5 октября 1975 года новую комету. В этом не было бы ничего особенно удивительного, если бы через час он не заметил еще одну, несколько более яркую новую комету. Мори стал первым в истории астрономом, которому повезло дважды в одну ночь.\n\nСледующую информацию запомните, предварительно разбив ее на несколько логически завершенных отрывков.\n\nНекий Жан Терель вступил во Французскую армию в семнадцатом веке, а вышел в отставку в девятнадцатом. Это кажется невероятным: он служил в армии на протяжении трех веков, так сколько же лет он прожил? Не так мало, хотя и не около трехсот, как может показаться. Жан Терель родился в Дижоне в 1684 году, вступил в армию шестнадцати лет, в 1699 году, на исходе века. Участвовал более чем в ста сражениях. В 1777 году, когда ему было 93 года, король Людовик XIV пожаловал старому служаке звание капитана. В 1802 году (Терелю было уже 118 лет) о нем узнал Наполеон. Вопреки нежеланию ветерана он уволил его в почетную отставку, назначив ежегодную пенсию в 1500 франков. Жан Терель умер в 1807 году, на сто двадцать третьем году жизни.\n\n2. Запомните даты техникой запоминания исторических дат.\n\n1847 Левицкий сконструировал фотокамеру с мехами\n\n1855 Максвелл разработал теорию цветности и аддитивного смешения цветов\n\n1880 Абней применил гидрохинон в качестве проявляющего вещества\n\n1888 Истмен создал и начал производить фотоаппараты для рулонной фотопленки\n\n1920 Шиловым получены патенты на проявочные машины для обработки рулонных фотопленок\n\n1935 Фирма «Кодак» изготовила цветную обращаемую фотопленку «Кодахром»\n\n3. Запомните международные телефонные коды. (Порядок набора: 8 гудок 10 код страны код города вызываемый номер телефона.)\n\nАвстралия (61) Канберра (62) Мельбурн (3) Сидней (2)\n\nАвстрия (43) Вена (1) Грац (316) Инсбрук (5222) Линц (732) Зальцбург (662)\n\nАргентина (54) Буэнос-Айрес (1) Кордоба (51) Санта-Фе (42)\n\nБельгия (32) Антверпен (3) Брюгге (50) Брюссель (2) Рент (91) Льеж (41)\n\n---\n\n## Домашнее задание к занятию 11\n\n1. Запомните текст, выделив в нем логически завершенные части. Запоминанию подлежит последовательность выделенных вами смысловых частей, а также вся точная информация текста. При соблюдении этих условий можно пересказывать тест своими словами.\n\nО пользе шелковицы\n\nДоктор медицинских наук, профессор А.Турова и врач Э.Сапожникова\n\nВ южных районах одним из самых популярных деревьев является шелковица или тут.\n\nЯгоды приятны на вкус, содержат сахара до 10 процентов (белые - до 20), главным образом фруктозу и глюкозу, органические кислоты (яблочную, лимонную), пектины, витамины, соли меди и железа. Последних особенно много в черных плодах. В листьях шелковицы большой набор витаминов: тиамин, рибофлавин, пиридоксин, никотиновая кислота, а также бета-ситостерин.\n\nЯгоды тута широко используются в восточной медицине. Так, во Вьетнаме из листьев шелковицы готовится препарат фомидол, который используется как средство, повышающее защитные силы организма при лечении кожных заболеваний и ревматизма. По биологическому действию он соответствует препаратам алоэ и биоседу. В Японии цветки шелковицы, перетертые с растительными маслами, вводят в состав косметических кремов.\n\nЧай из сушеных ягод вызывает выделение пота. Его применяют при простудных заболеваниях, а также при гипертонической болезни.\n\nПри заболевании сердца ягоды употребляются как мочегонное средство по 200- 250 граммов в день.\n\nСок из ягод шелковицы пьют по 3-2 столовые ложки в день при гипертонической болезни, при заболеваниях сердца, связанных с ослаблением работы сердечной мышцы, при миокард иод истрофиях, атеросклерозе, ишемической болезни сердца, мерцательной аритмии, тахикардии и экстрасистолии. Лечебный курс - три недели. Принимают ежедневно 200- 300 граммов свежих ягод или настой из сушеных.\n\nЧерная шелковица в любом виде полезна при малокровии. Как вспомогательное средство при сахарном диабете используют свежие ягоды или настой из сухих ягод шелковицы.\n\nВ народе применяют сухие листья шелковицы: их измельчают в порошок и посыпают пищу - творог, винегрет по половине чайной ложки 1-2 раза в день. Принимают и отвар из молодых веточек. Их режут на кусочки по 2- 3 сантиметра и высушивают в тени. Для приготовления отвара 3-4 кусочка заливают двумя стаканами воды, доводят до кипения, кипятят 10 минут, настаивают 2 часа. Принимают по четверти стакана в день дробными дозами. Курс лечения 3-4 недели, повторный курс лечения проводят после двухнедельного перерыва.\n\nНастой ягод шелковицы применяют для полоскания полости рта при ангинах и стоматитах.\n\nНастой из сухих ягод готовят так: две столовые ложки размельченных ягод заливают стаканом кипятка, настаивают 4 часа, процеживают, выпивают в течение дня дробными порциями (диабетикам), учитывая разрешенное врачом количество жидкости. После приема настоев шелковицы не рекомендуют пить обычный чай, так как его танины осаждают полезные вещества тута, переводя их в нерастворимые соединения.\n\nДля длительного хранения отжатый сок выпаривают до консистенции густого сиропа (до трети первоначального объема). Такой сироп называют бекмес (душаб). Он имеет приятный вкус и сохраняет все лечебные свойства ягод шелковицы.\n\nОтходы после отжима сока высушивают и в дальнейшем используют для приготовления настоев, как и ягоды.\n\nСвежий жом шелковицы оставляют для брожения и затем используют наружно для ванн и припарок при заболеваниях суставов и невралгиях. Для больных сахарным диабетом ягоды консервируют в виде густого компота без сахара.\n\nПри перечисленных выше заболеваниях шелковица может служить лишь вспомогательным средством, не заменяя медикаментозных назначений лечащего врача.\n\nПлоды тута используют в пищевой промышленности для приготовления напитков, уксуса, мармелада, пастилы, варенья, компотов. У народов Средней Азии тутовые ягоды - свежие и сухие - служат заменителем сахара. Из выжимок ягод тута выпекают пряники, которые могут храниться длительное время.",
  "7": "## Домашнее задание к занятию 8\n\n1. Преобразуйте числовую таблицу в образные коды. Добивайтесь автоматизма кодирования. Используйте метроном.\n\n05 89 37 17 86 31 93 15 45 07\n\n28 62 83 70 03 78 43 00 99 26\n\n71 46 90 61 91 54 51 66 34 55\n\n85 92 23 94 24 11 74 96 97 08\n\n63 72 47 16 84 32 95 20 50 39\n\n29 02 52 77 38 67 09 58 75 14\n\n73 87 10 41 19 65 68 44 01 69\n\n18 64 82 30 59 33 48 76 80 49\n\n88 36 53 25 79 06 35 56 40 81\n\n22 98 04 60 12 42 21 13 57 27\n\n2. Запомните слова приемом «Цепочка».\n\nСПУТНИК ОЧКИ ГАЛСТУК МОНАХ ПАЛЕЦ ОЗЕРО ГЛОБУС ЖЕЛТОК МАСТЕР ПЕЧАТЬ КОЛЕСО КАМЕНЬ КРИСТАЛЛ КОСЫНКА ФЛАГ ЗДАНИЕ ПАПКА ЗНАЧОК ОБЪЕКТИВ ВОЛОС ПРИБОР СТЕКЛО КОВЕР КУПОЛ ВИНТ МЯЧ ШАХМАТЫ ПЛОЩАДЬ КРЕСЛО КЛЕТКА ВОРОНА МАСКА ОБЛАКО БАШНЯ ТРАВА КОЛОКОЛ БАРАН ИКОНА ЗВЕЗДА ОГРЫЗОК\n\n3. Запомните числа под порядковыми номерами. Ассоциации образуйте приемом «Матрешка» (чтобы не путать порядковые номера с запоминаемыми числами).\n\n1. 72 2. 74 3. 23 4. 92 5. 16 6. 84\n\n7. 32 8. 26 9. 38 10. 99 11. 90 12. 30\n\n13. 26 14. 91 15. 20 16. 90 17. 92 18. 47\n\n19.48 20.41 21.11 22.21 23.02 24.11\n\n25. 63 26. 95 27. 68 28. 60 29. 10 30. 20\n\n31. 13 32. 91 33. 64 34. 32 35. 22 36. 28\n\n37. 99 38. 74 39. 61 40. 09 41. 17 42. 27\n\n43. 58 44. 74 45. 40 46. 00 47. 16 48. 34\n\n49. 92 50. 62 51. 21 52. 44 53. 63 54. 38\n\n55. 49 56. 65 57. 81 58. 87 59. 11 60. 49\n\n61. 26 62. 62 63. 35 64. 67 65. 61 66. 64\n\n67. 58 68. 13 69. 38 70. 12 71. 47 72. 84\n\n73. 46 74. 26 75. 63 76. 16 77. 56 78. 14\n\n79. 64 80. 69 81. 68 82. 13 83. 65 84. 24\n\n85. 82 86. 68 87. 70 88. 51 89. 10 90. 03\n\n91. 12 92. 17 93. 73 94. 42 95. 14 96. 77\n\n97. 78 98. 08 99. 17\n\nСамоконтроль при выполнении упражнений.\n\nКонтрольное время запоминания упражнения № 3 - 15 минут (9 секунд на одну ассоциацию). Время контрольного припоминания, с выписыванием чисел и порядковых номеров, 8-10 минут. Количество ошибок и пропусков при припоминании упражнения - 10 (одна ошибка на 10 чисел).\n\n4. В течение дня мысленно повторяйте упражнения 8-го занятия (телефонные номера кинотеатров и фирм). Добивайтесь свободного припоминания информации. Используйте для тренировок время поездок в метро, автобусе, пеших прогулок.\n\nОбращаем ваше внимание: мысленную проработку запомнившихся сведений осуществлять сложнее, чем запоминание этих сведений. Поэтому следует усиленно тренироваться припоминать большие объемы информации с начала до конца, без перерывов.\n\n---\n\n## Домашнее задание к занятию 12\n\n1. Мысленно повторяйте сведения, которые вы запомнили на занятии. Добейтесь эффекта непосредственного припоминания, когда фамилии и терминология припоминаются без затруднений.\n\n2. Запомните отдельным блоком точные сведения из истории начала 19 века. Разделите информацию на четыре короткие последовательности, собрав их на произвольном образе.\n\nПолонез - танец, которым открывали балы в начале 19 века.\n\nКанцлер - высший штатский чин в «Табели о рангах».\n\nЗасулич - революционерка, в 1878 году совершила покушение на Петербургского градоначальника Трепова.\n\nУваров - русский генерал, возглавлял кавалерию в Бородинском сражении.\n\nБоткин - русский врач, один из основателей эпидемиологического общества в России.\n\nРостовцев - первый председатель Редакционных комиссий, созданых в 1859 году; занимались рассмотрением проектов крестьянской реформы.\n\nНежин - город, в котором организован третий по счету лицей (после Царскосельского и Ярославского).\n\nПанин - председатель Редакционных комиссий после 1860 года.\n\nСеченов - физиолог, один из основателей первой физиологической лаборатории в России.\n\nКанкрин - министр финансов при Николае I, провел в 1840-х годах денежную реформу.\n\nПавел - Российский император, магистр Мальтийского ордена.\n\nКоник - большая скамья-ящик с крышкой, у стен в крестьянских избах.\n\nКибальчич - народоволец, автор проекта реактивного двигателя, казнен в 1881 году.\n\nКрылов - русский судостроитель, академик.\n\nВериги - цепи, носили монахи и юродивые.\n\nДоломан - гусарский мундир в русской армии.\n\nБлагоев - болгарский революционер-марксист, один из руководителей партии русских социал-демократов.\n\nПестель - один из руководителей Южного общества, казнен в 1826 году.\n\nПлатов - русский генерал, командовавший казачьими частями в О.В. 1812 года.\n\nСенат - высшая кассационная инстанция Российской империи по судебной реформе 1864 года.\n\nПариж - европейская столица, законодательница моды во 2-й половине 19 в.\n\nКлирос - место для хора в христианском храме.\n\nШевырев - лит. критик, поэт, общ. деятель, сотрудничал с Погодиным в «Москвитянине».\n\nДурново - министр внутренних дел, при нем приняты положения о земских начальниках и земских учреждениях.\n\nСмирдин - крупный книгоиздатель и просветитель, в 18301840 гг., удешевивший стоимость книг.\n\nВоронихин - архитектор, автор проекта Казанского собора.\n\nБелинский - литературный критик, публицист, сотрудничал с журналом «Отечественные записки».\n\nСиделец - в начале 19 века так назывался приказчик в лавке.\n\nНахимов - командующий русской эскадрой в Синопском сражении.\n\nЗахаров - архитектор, автор проекта здания Адмиралтейства в Петербурге.\n\nТолстой - министр внутренних дел в 1882-1889 гг.\n\nПирогов - русский хирург, участник обороны Севастополя, впервые применил наркоз.\n\nЛотман - автор монографии «Беседы о русской культуре - быт и традиции русского дворянства в 18 начале 19 века».\n\nНечаев - глава организации «Топор и народная расправа», созданной в Москве в 1869 году.\n\nКорец - крестьянское название ковша для воды.\n\nПавел - российский царь, приказал прикрепить на стене Зимнего дворца ящик для петиций к самодержавцу.",
  "8": "## Домашнее задание к занятию 13\n\nМысленно последовательно припомните все знаки азбуки хираганы. Представляя мысленно знак, проговаривайте его произношение.\n\nВ табличке знаки хираганы расположены в случайном порядке Называйте знаки азбуки вслух. Добивайтесь, чтобы перекодирование знаков в звуки происхолило без задержек.\n\n3. Напишите хираганой следующие слова:\n\nСАРА САКАНА ТАНА НАКА КУРА НИХОН КАРАН ОСАКЭ МОНО МИМИ КАО КАТА ХАРА КОТОБА ИТАИ НУНО СУММ ЯСАИ КИМОНО КИБИ ХИРОСА АКАСА КУРА НУНО КИКАИ НИРУ КАЭРУ TOMATO САКУРА АСА УМЭ АТАТАКАИ КАМИ\n\nПеревод слов:\n\nТарелка - рыба - полка - внутри - загон - Япония - кран - водка (рисовая) - вещь - уши - лицо - плечи - живот - слово - болит - повязка - тушь - зелень - халат - гречка - ширина - краснота - гараж - шарф - механизм - варить пищу - менять - помидоры - вишня - утро - слива - тепло - бумага (бог, волосы)\n\n4. Из плотного картона сделайте 46 карточек и напишите на них знаки азбуки хираганы. Перемешивая карточки, вы легко получите случайную последовательность знаков.\n\nКарточки являются одновременно и тренажером, и тестом на качество запоминания знаков. Если у вас получается называть знаки со скоростью 0,5-1 секунда, значит, в вашем мозгу образовалась непосредственная связь между речевым и зрительным анализатором (разномодальная ассоциация, рефлекторная связь).\n\nСлучайная последовательность карточек - универсальный метод тренировки. Используя его, вы можете достаточно быстро доводить до рефлекторного уровня припоминания самые разные сведения: знаки, иностранные слова, образные коды чисел, исторические даты, новую терминологию, фамилии. Разумеется, все эти сведения предварительно необходимо запомнить методами мнемотехники и хорошо закрепить в памяти. Карточки служат именно для доводки информации до автоматического уровня припоминания.\n\nНапример, вы можете считать, что в вашем мозгу сформировались образные коды двузначных чисел, если при восприятии числа на слух или на бумаге в вашем воображении мгновенно появляется соответствующий образ (образ должен возникать сам, автоматически, без вашего сознательного участия).\n\n---\n\n## Домашнее задание к занятию 14\n\n1. Запомните слова техникой запоминания иностранных слов. Вспомните, запишите, проверьте правильность припоминания.\n\nАТАМА ГОЛОВА КАМИ ВОЛОСЫ\n\nМИМИ УШИ МЭ ГЛАЗА\n\nХАНА ЦВЕТОК КАО ЛИЦО\n\nКЭЧИ РОТ ХА ЗУБЫ\n\nЩТА ЯЗЫК НОДО ГОРЛО\n\nКУБИ ШЕЯ КАТА ПЛЕЧИ\n\nСЭНАКА СПИНА МУНЭ ГРУДЬ\n\nОППАИ ГРУДЬ (ЖЕН.) ХАРА ЖИВОТ\n\nКОЩИ БЕДРА ХИДЗА КОЛЕНИ\n\nАТО СТУПНЯ АЩИ НОГА\n\nУДЭ РУКА ТЭ КИСТЬ\n\nЙУБИ ПАЛЕЦ ЦУМЭ НОГОТЬ\n\nЦУДЗО-О МОЗГ ЩИНДЗО-О СЕРДЦЕ\n\nТАНДЗО-О ПЕЧЕНЬ ХИХУ КОЖА\n\nКЕЩИ УЧИТЕЛЬ КОКУБАН ДОСКА (ШК.)\n\nЧОКУ МЕЛ КАКУ ПИСАТЬ\n\nУЧИ ДОМ ХАТАРАКУ РАБОТАТЬ\n\nМОРИ ЛЕС КИНО-О ВЧЕРА\n\nДОКО ГДЕ? ДАЙНГАКУ УНИВЕРСИТЕТ\n\nТОМОДАЧИ ТОВАРИЩ ИСЫ СТУЛ\n\nО-ОКИ-И БОЛЬШОЙ ДЭНВА ТЕЛЕФОН\n\nХАНАСУ ГОВОРИТЬ ЩИБАИ ТЕАТР\n\nГИН СЕРЕБРО КИН ЗОЛОТО\n\nОТОМЭ ДЕВУШКА МИННА ВСЕ"
};
